import json

def allarmi(testo_json, soglia):
    dati = json.loads(testo_json)
    out = []
    for l in dati["letture"]:
        v = l["grandezze"].get("vib")
        if v is not None and v > soglia:
            out.append(l["t"][11:16])
    return out

print(allarmi('{"letture": [{"t": "2026-03-14T08:20:00", "grandezze": {"vib": 3.4}}]}', 3.0))
